-- Integration checks always roll back: no test people/orders/completions remain.
begin;
do $$declare admin_id uuid;scanner_id uuid;setup_id uuid;result jsonb;report jsonb;oid text:='TEST-DUMP-ORDER';wid text:='TEST-DUMP-WORK';jid text:='TEST-DUMP-JOB';pid text:='TEST-DUMP-PERSON';code text:='REUSE-0123456789ABCDEF';req uuid:=gen_random_uuid();rev bigint;today date:=(now() at time zone 'America/Chicago')::date;week date:=date_trunc('week',now() at time zone 'America/Chicago')::date;begin
 select id into admin_id from public.staff_profiles where role='admin' and active limit 1;
 select id into scanner_id from public.staff_profiles where role='box_scanner' and active limit 1;
 select id into setup_id from public.staff_profiles where role='box_setup' and active limit 1;
 if admin_id is null or scanner_id is null or setup_id is null then raise exception 'Provision test roles first';end if;
 insert into public.people(id,name,kind,hours_per_day,data) values(pid,'Rollback test individual','individual',6,'{}');
 insert into public.orders(id,customer_id,stage,data) values(oid,(select id from public.customers limit 1),1,jsonb_build_object('title','Rollback test','quantity',250,'perPack',25,'required',today,'expected',today));
 insert into public.work_orders(id,order_id,quantity,pieces_per_pack,data) values(wid,oid,250,25,'{"type":"Assembly","seconds":30,"packSeconds":0,"hoursPerDay":6,"description":"Test assembly","instructions":"Test"}');
 insert into public.sub_jobs(id,work_order_id,quantity,data) values(jid,wid,250,'{"name":"Test sub-job","packType":"Box"}');
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.app_availability(today,today+6,pid,'available',6,array[0,1,2,3,4,5,6]);
 result:=public.app_availability(today,today+6,pid);if jsonb_array_length(result)<>7 then raise exception 'Availability range failed';end if;
 perform public.app_attendance(today,pid,'present','09:00','14:00',3.5,0);
 begin perform public.app_attendance(today,pid,'absent',null,null,0,0);raise exception 'Expected stale attendance rejection';exception when serialization_failure then null;end;
 report:=public.app_individual_timesheet(pid,week);if report#>>array['data','days',today::text,'arrival']<>'09:00' then raise exception 'Attendance timesheet overlay failed';end if;
 perform set_config('request.jwt.claim.sub',setup_id::text,true);
 perform public.app_dumping_assign(code,jid,pid,100);
 -- Simulate a legacy outstanding box: new APIs now prohibit creating this overlap.
 insert into public.boxes(id,sub_job_id,person_id,quantity,data) values('TEST-DUMP-BOX',jid,pid,30,'{}');

 begin perform public.app_dumping_scan(code,req);raise exception 'Setup user scanned work';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',scanner_id::text,true);
 result:=public.app_dumping_scan(code,req,200);if (result->>'pieces')::int<>200 then raise exception 'Default batch failed';end if;
 result:=public.app_dumping_scan(code,req);if not (result->>'duplicate')::boolean or (select completed from public.sub_jobs where id=jid)<>200 then raise exception 'Retry counted twice';end if;
 begin perform public.app_dumping_scan(code,gen_random_uuid());raise exception 'Expected duplicate guard';exception when raise_exception then if sqlerrm not like 'Too soon to scan%' then raise;end if;end;
 update public.dumping_assignments set last_scan_at=clock_timestamp()-interval '51 minutes' where id=code;
 begin perform public.app_dumping_scan(code,gen_random_uuid(),200);raise exception 'Double load accepted before its fill time';exception when raise_exception then if sqlerrm not like 'Too soon to scan%' then raise;end if;end;
 update public.dumping_assignments set last_scan_at=clock_timestamp()-interval '101 minutes' where id=code;
 begin perform public.app_dumping_scan(code,gen_random_uuid());raise exception 'Expected capacity guard';exception when raise_exception then if sqlerrm not like 'Batch exceeds%' then raise;end if;end;
 begin perform public.app_dumping_scan(code,gen_random_uuid(),201);raise exception 'Over two loads accepted';exception when raise_exception then if sqlerrm not like 'Batch exceeds%' then raise;end if;end;
 perform public.app_dumping_scan(code,gen_random_uuid(),20);
 if (select completed from public.sub_jobs where id=jid)<>220 then raise exception 'Partial final batch failed';end if;
 perform public.app_complete_box('TEST-DUMP-BOX',30);
 if (select completed from public.sub_jobs where id=jid)<>250 then raise exception 'Mixed box/dumping totals failed';end if;
 begin perform public.app_attendance(today);raise exception 'Scanner read roster';exception when insufficient_privilege then null;end;
 begin perform public.app_availability(today,today);raise exception 'Scanner read availability';exception when insufficient_privilege then null;end;
 result:=public.app_scanner_daily_work(today);
 if not exists(select 1 from jsonb_array_elements(result) x where x->>'personId'=pid and (x->>'pieces')::int=250 and (x->>'completions')::int=3) then raise exception 'Daily mixed totals incorrect';end if;
 result:=public.app_scanner_daily_work(today-1);
 if exists(select 1 from jsonb_array_elements(result) x where x->>'personId'=pid) then raise exception 'Wrong day leaked';end if;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform public.app_scanner_daily_work(today);raise exception 'Anonymous history accepted';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 report:=public.app_individual_timesheet(pid,week);
 if (select sum((value->>'pieces')::int) from jsonb_array_elements(report->'entries'))<>250 then raise exception 'Timesheet pieces wrong';end if;
 result:=manufacturing_private.read_order(oid);rev:=(result->>'_revision')::bigint;
 begin perform public.app_save_order(jsonb_set(result,'{workOrders,0,jobs,0,completed}','0'),rev,'Test');raise exception 'Expected production total guard';exception when raise_exception then if sqlerrm not like 'Completed pieces cannot%' then raise;end if;end;
 perform public.app_dumping_close(code);
 perform set_config('request.jwt.claim.sub',scanner_id::text,true);
 begin perform public.app_dumping_scan(code,gen_random_uuid(),1);raise exception 'Closed QR accepted';exception when raise_exception then if sqlerrm not like 'Assignment is closed%' then raise;end if;end;
 if has_function_privilege('anon','public.app_dumping_scan(text,uuid,integer)','execute') or has_table_privilege('authenticated','public.dumping_completions','select') then raise exception 'Direct access exposed';end if;
end$$;
rollback;
